//! Appending data files to a dataset ("Anexar dados", manual
//! articles-appending-data.htm and articles-append-conflicts.htm): a logger
//! writes one file a day, and the dataset is the first file with the others
//! appended. The rules, as the original applies them by default (checked in
//! its manual and code, ARQUITETURA 2026-10-18):
//! - **Links by name:** an appended column goes into the master column with
//!   its id. Without one, it is linked by its properties (the original's
//!   autogenerated links): into the one master column of the same type,
//!   subtype, units and height that the file does not already fill, so a
//!   sensor renamed in the logger keeps its column. Otherwise it becomes a
//!   new column.
//! - **Time:** the record grows to cover every file, before, after or with a
//!   gap; the time step must be the same, and the files on the same phase.
//! - **Overlap:** the master's data stays except where it is missing (the
//!   original's default, "use master data unless it's missing"); among the
//!   appended files, the earlier one wins.
//! - **Properties:** the master's dataset and column properties stay.
//!
//! [`merge`] places every file on the common grid in one pass, so 200 daily
//! files cost one copy of the record, not 200. Derived columns, flags and
//! edits come after, as for a single file (the wasm session carries flags
//! and edits over by time stamp, [`crate::flags::carry_over`]).
use crate::error::CoreError;
use crate::model::Dataset;
use std::sync::Arc;

/// A sparse record could be mostly empty grid: the union of the files may
/// hold at most this many steps per row read, like a single file's grid.
const MAX_STEPS_PER_ROW: i64 = 10;
/// Steps allowed beyond that, so short files are never refused.
const SLACK_STEPS: i64 = 1_000;

/// What happened to one appended file.
#[derive(Debug, Clone, PartialEq)]
pub enum AppendOutcome {
    /// It was appended.
    Appended {
        /// Its steps on the grid.
        steps: usize,
        /// Columns it added to the master, by id.
        new_columns: Vec<String>,
        /// Its columns linked by properties: (its id, the master's id).
        linked: Vec<(String, String)>,
        /// Values it put where the record had none.
        filled: usize,
        /// Values it had where the record already had data (left as they were).
        overlapped: usize,
    },
    /// It was left out, for this reason.
    Refused(CoreError),
}

/// `master` with `appended` (in order) merged in by the rules above; one
/// outcome per appended file. A file that cannot join (another step, off
/// phase, a record too sparse) is refused and the rest still join.
/// O(columns × steps of the result + values read).
pub fn merge(mut master: Dataset, appended: Vec<Dataset>) -> (Dataset, Vec<AppendOutcome>) {
    let step = master.step_s;
    let mut outcomes = Vec::with_capacity(appended.len());
    let mut accepted = Vec::with_capacity(appended.len());
    let (mut start, mut end) = (master.start, master.start + master.len as i64 * step);
    let mut rows = master.len as i64;
    for file in appended {
        let refusal = if file.step_s != step {
            Some(CoreError::AppendStepMismatch { master_s: step, appended_s: file.step_s })
        } else if (file.start - master.start).rem_euclid(step) != 0 {
            Some(CoreError::AppendOutOfPhase { offset_s: (file.start - master.start).rem_euclid(step) })
        } else {
            let (new_start, new_end) = (start.min(file.start), end.max(file.start + file.len as i64 * step));
            let steps = (new_end - new_start) / step;
            (steps > MAX_STEPS_PER_ROW * (rows + file.len as i64) + SLACK_STEPS)
                .then_some(CoreError::TimestampsSpanTooMany { steps, step_s: step, rows: rows as usize + file.len })
        };
        match refusal {
            Some(error) => outcomes.push(AppendOutcome::Refused(error)),
            None => {
                start = start.min(file.start);
                end = end.max(file.start + file.len as i64 * step);
                rows += file.len as i64;
                outcomes.push(AppendOutcome::Appended { steps: file.len, new_columns: Vec::new(), linked: Vec::new(), filled: 0, overlapped: 0 });
                accepted.push((outcomes.len() - 1, file));
            }
        }
    }
    if accepted.is_empty() {
        return (master, outcomes);
    }
    let len = ((end - start) / step) as usize;
    let at = |file_start: i64| ((file_start - start) / step) as usize;
    // The master's columns on the new grid, then each file filling gaps.
    let master_offset = at(master.start);
    let mut values: Vec<Vec<f64>> = master
        .columns
        .iter()
        .map(|column| {
            let mut placed = vec![f64::NAN; len];
            placed[master_offset..master_offset + column.values.len()].copy_from_slice(&column.values);
            placed
        })
        .collect();
    for (outcome_index, file) in accepted {
        let offset = at(file.start);
        let mut new_columns = Vec::new();
        let mut linked = Vec::new();
        let (mut filled, mut overlapped) = (0, 0);
        // Master columns this file fills by name: a property link may not take them.
        let mut taken: Vec<bool> = master.columns.iter().map(|existing| file.columns.iter().any(|column| column.id == existing.id)).collect();
        for column in &file.columns {
            let by_name = master.columns.iter().position(|existing| existing.id == column.id);
            let by_properties = || {
                let mut candidates = (0..master.columns.len()).filter(|&index| {
                    let existing = &master.columns[index];
                    !taken[index]
                        && existing.derived.is_none()
                        && existing.kind == column.kind
                        && existing.subtype == column.subtype
                        && existing.units == column.units
                        && existing.height_m.is_some()
                        && existing.height_m == column.height_m
                });
                let first = candidates.next()?;
                candidates.next().is_none().then_some(first)
            };
            let target = match by_name.or_else(by_properties) {
                Some(target) => {
                    if by_name.is_none() {
                        linked.push((column.id.clone(), master.columns[target].id.clone()));
                        taken[target] = true;
                    }
                    target
                }
                None => {
                    let mut added = column.clone();
                    // A parent is an index into the appended file: find it again by id.
                    added.parent = column.parent.and_then(|parent| {
                        let parent_id = &file.columns[parent].id;
                        master.columns.iter().position(|existing| &existing.id == parent_id)
                    });
                    added.values = Arc::from([]);
                    new_columns.push(column.id.clone());
                    master.columns.push(added);
                    values.push(vec![f64::NAN; len]);
                    taken.push(true);
                    master.columns.len() - 1
                }
            };
            for (slot, &value) in values[target][offset..offset + column.values.len()].iter_mut().zip(column.values.iter()) {
                if value.is_nan() {
                    continue;
                }
                if slot.is_nan() {
                    *slot = value;
                    filled += 1;
                } else {
                    overlapped += 1;
                }
            }
        }
        outcomes[outcome_index] = AppendOutcome::Appended { steps: file.len, new_columns, linked, filled, overlapped };
    }
    for (column, placed) in master.columns.iter_mut().zip(values) {
        column.values = placed.into();
    }
    master.start = start;
    master.len = len;
    (master, outcomes)
}
